import{Z as t,e as o,f as a,a0 as n}from"./chunks/framework.DmpHOl9T.js";const d=JSON.parse('{"title":"OOPSpam","description":"","frontmatter":{},"headers":[],"relativePath":"integrations/captchas/oopspam.md","filePath":"integrations/captchas/oopspam.md","lastUpdated":1781527112000}'),s={name:"integrations/captchas/oopspam.md"};function i(r,e,p,l,h,c){return o(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="oopspam" tabindex="-1">OOPSpam <a class="header-anchor" href="#oopspam" aria-label="Permalink to &quot;OOPSpam&quot;">​</a></h1><p>Follow the below steps to connect Formie to the OOPSpam API.</p><h3 id="step-1-open-the-captcha-settings" tabindex="-1">Step 1. Open the Captcha Settings <a class="header-anchor" href="#step-1-open-the-captcha-settings" aria-label="Permalink to &quot;Step 1. Open the Captcha Settings&quot;">​</a></h3><ol><li>Navigate to <strong>Formie</strong> → <strong>Settings</strong> → <strong>Spam Protection</strong> → <strong>Captchas</strong>.</li><li>Select <strong>OOPSpam</strong> in the left-hand sidebar.</li><li>Turn on <strong>Enabled</strong>.</li></ol><h3 id="step-2-get-your-oopspam-api-key" tabindex="-1">Step 2. Get Your OOPSpam API Key <a class="header-anchor" href="#step-2-get-your-oopspam-api-key" aria-label="Permalink to &quot;Step 2. Get Your OOPSpam API Key&quot;">​</a></h3><ol><li>Go to <a href="https://www.oopspam.com/" target="_blank" rel="noreferrer">OOPSpam</a> and create an account, or sign in to an existing one.</li><li>Open your OOPSpam dashboard.</li><li>Copy the API key shown under <strong>Your API key</strong> on the main dashboard page.</li></ol><h3 id="step-3-connect-formie-to-oopspam" tabindex="-1">Step 3. Connect Formie to OOPSpam <a class="header-anchor" href="#step-3-connect-formie-to-oopspam" aria-label="Permalink to &quot;Step 3. Connect Formie to OOPSpam&quot;">​</a></h3><ol><li>Paste the API key into the <strong>API Key</strong> field in Formie.</li><li>Choose a <strong>Spam Threshold</strong>. Formie defaults to <code>3</code>, which matches OOPSpam&#39;s recommended starting point.</li><li>Save the captcha settings.</li></ol><h3 id="step-4-form-setting" tabindex="-1">Step 4. Form Setting <a class="header-anchor" href="#step-4-form-setting" aria-label="Permalink to &quot;Step 4. Form Setting&quot;">​</a></h3><ol><li>Go to the form you want to protect.</li><li>Enable <strong>OOPSpam</strong> for that form.</li><li>For multi-page forms, turn on <strong>Show on All Pages</strong> if the spam check should run on every page instead of only the final submit step.</li><li>Save the form.</li></ol><p>OOPSpam screens submissions in the background, so there is no visible challenge on the front end.</p><h2 id="verify-a-submission" tabindex="-1">Verify a Submission <a class="header-anchor" href="#verify-a-submission" aria-label="Permalink to &quot;Verify a Submission&quot;">​</a></h2><p>Save the form, open it on your site and submit recognisable test values. Submit through the site and check the resulting submission and spam state. A saved credential alone does not verify the visitor-facing challenge or server-side check.</p><p>If nothing arrives, check whether integration conditions matched, whether the submission was complete and non-spam, and whether Craft’s queue has processed the job. A successful connection check verifies credentials; it does not prove that field mapping and delivery work. See <a href="/integrations/connect-and-test-an-integration">Connect and Test an Integration</a> for a complete mapping and verification workflow.</p>',14)])])}const g=t(s,[["render",i]]);export{d as __pageData,g as default};
